<?php
require_once 'config.php';if(!currentUser())redirect('login.php?next=checkout');$cart=$_SESSION['cart']??[];if(!$cart)redirect('cart.php');
$ids=array_keys($cart);$marks=implode(',',array_fill(0,count($ids),'?'));$s=$pdo->prepare("SELECT * FROM products WHERE id IN ($marks) AND active=1");$s->execute($ids);$products=$s->fetchAll();$total=0;foreach($products as $p){$total+=(float)$p['price']*(int)$cart[$p['id']];}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$method=$_POST['payment']??'';if(!in_array($method,['PIX','Boleto','Cartão'],true))$error='Selecione uma forma de pagamento.';
else{try{$pdo->beginTransaction();$check=$pdo->prepare("SELECT stock,price FROM products WHERE id=? FOR UPDATE");foreach($products as $p){$check->execute([$p['id']]);$fresh=$check->fetch();if(!$fresh||(int)$fresh['stock']<(int)$cart[$p['id']])throw new Exception('Estoque insuficiente para '.$p['name']);}
$order=$pdo->prepare("INSERT INTO orders(user_id,total,payment_method) VALUES(?,?,?)");$order->execute([currentUser()['id'],$total,$method]);$orderId=(int)$pdo->lastInsertId();$item=$pdo->prepare("INSERT INTO order_items(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)");$update=$pdo->prepare("UPDATE products SET stock=stock-? WHERE id=?");foreach($products as $p){$qty=(int)$cart[$p['id']];$item->execute([$orderId,$p['id'],$qty,$p['price']]);$update->execute([$qty,$p['id']]);}$pdo->commit();unset($_SESSION['cart']);$_SESSION['last_order']=$orderId;redirect('success.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof PDOException?'Não foi possível concluir o pedido.':$e->getMessage();}}}
$pageTitle='Finalizar compra';include 'includes/header.php';?>
<div class="page-head"><div class="container"><div class="section-kicker">ÚLTIMA ETAPA</div><h1>FINALIZAR PEDIDO</h1></div></div><section class="section"><div class="container"><div class="row g-4"><div class="col-lg-7"><div class="dark-panel"><h2 class="section-title">FORMA DE PAGAMENTO</h2><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><label class="form-label">Selecione uma opção</label><select class="form-select mb-4" name="payment" required><option value="">Escolher...</option><option>PIX</option><option>Boleto</option><option>Cartão</option></select><p class="muted small">Pagamento demonstrativo: nenhuma cobrança real será realizada.</p><button class="btn-red w-100">CONFIRMAR PEDIDO</button></form></div></div><div class="col-lg-5"><div class="dark-panel"><h3 class="section-title">RESUMO</h3><?php foreach($products as $p): ?><div class="d-flex justify-content-between mb-3"><span><?= e($p['name']) ?> × <?= (int)$cart[$p['id']] ?></span><strong><?= money($p['price']*$cart[$p['id']]) ?></strong></div><?php endforeach; ?><hr><div class="d-flex justify-content-between"><strong>TOTAL</strong><strong class="price"><?= money($total) ?></strong></div></div></div></div></div></section><?php include 'includes/footer.php'; ?>
